getById.exampleCs:
Events.FromClient("bank:open", (Player player, JsValue payload) =>
{
    var vault = Stash.GetById(payload["id"].AsNumber());
    if (vault?.IsStorage == true)
    {
        vault.Open(player);
    }
});

