adopt.example:
// This chest opens only with its own key.
const { Stash } = kcds.world;

const [closest] = Stash.levelChests(player.position, 3);
const keyedChest = closest && Stash.adopt(closest.placedGuid);
if (keyedChest) {
  keyedChest.keyClass = kcds.players.Items.effective('key_custom')?.id ?? '';
  keyedChest.canBePicked = false;
  keyedChest.locked = true;
}

adopt.exampleCs:
// This chest opens only with its own key.
var closest = Stash.LevelChests(player.Position, 3).FirstOrDefault();
var keyedChest = closest.IsNull ? null : Stash.Adopt(closest["placedGuid"]);
if (keyedChest != null)
{
    var key = Items.Effective("key_custom");
    keyedChest.KeyClass = key.IsNull ? "" : key["id"].AsString();
    keyedChest.CanBePicked = false;
    keyedChest.Locked = true;
}

